"""Write results/main_table.md from results/tables/ablation_hybrid.csv (generated by evaluate_hybrid.py)."""
import os, pandas as pd
REPO = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
df = pd.read_csv(os.path.join(REPO, 'results', 'tables', 'ablation_hybrid.csv'))
lines = ['| Detector | Configuration | P | R | mAP@.5 | mAP@.5:.95 |', '|---|---|---|---|---|---|']
for _, r in df.iterrows():
    lines.append(f"| {r.detector} | {r.config} | {r.P:.3f} | {r.R:.3f} | {r.mAP50:.3f} | {r.mAP50_95:.3f} |")
open(os.path.join(REPO, 'results', 'main_table.md'), 'w').write('\n'.join(lines) + '\n')
print('\n'.join(lines))